import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/Chat.css";

const Chat = () => {
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const user = JSON.parse(localStorage.getItem("user"));

  console.log("✅ Logged-in user from localStorage:", user);

  useEffect(() => {
    if (!user || !user.userId) {
      console.warn("⚠️ No user ID found in localStorage!");
      return;
    }

    const fetchConversations = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/conversations/${user.userId}`);
        console.log("✅ Fetched conversations:", res.data);
        setConversations(res.data);
      } catch (err) {
        console.error("❌ Error fetching conversations:", err);
      }
    };

    fetchConversations();
  }, [user]);

  return (
    <div className="chat-container">
      <div className="chat-sidebar">
        <h3>Messages</h3>
        {conversations.length === 0 ? (
          <p className="empty-msg">No conversations found.</p>
        ) : (
          <ul className="conversation-list">
            {conversations.map((conv) => (
              <li
                key={conv._id}
                onClick={() => setSelectedConversation(conv)}
                className={selectedConversation?._id === conv._id ? "active" : ""}
              >
                <strong>{conv.participantUsernames.find(name => name !== user.username)}</strong>
                <p className="last-message">{conv.lastMessage}</p>
              </li>
            ))}
          </ul>
        )}
      </div>

      <div className="chat-main">
        <h3>Chat</h3>
        <div className="chat-messages">
          {selectedConversation ? (
            <p>Select a conversation to view messages (To be implemented)</p>
          ) : (
            <p className="empty-msg">No conversation selected</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default Chat;
